const cpus = os.cpus();
console.log(cpus.length > 0); // true
console.log(cpus[0].model.length > 0); // true

const total = os.totalmem();
const free = os.freemem();
console.log(free > 0 && free <= total); // true

const nis = os.networkInterfaces();
for (const name of Object.keys(nis)) {
  for (const ni of nis[name]) console.log(name, ni.family, ni.address, ni.cidr);
}

os.setPriority(10);
console.log(os.getPriority()); // 10
try { os.getPriority(999999) } catch (e: any) { console.log(e.info.code) } // ESRCH
